package com.autoops.execution.realtime;import org.springframework.stereotype.Component;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import java.io.IOException;import java.util.*;import java.util.concurrent.*;@Component public class ExecutionEventPublisher{private final Map<Long,List<SseEmitter>> emitters=new ConcurrentHashMap<>();public SseEmitter subscribe(Long id){SseEmitter e=new SseEmitter(0L);emitters.computeIfAbsent(id,k->new CopyOnWriteArrayList<>()).add(e);e.onCompletion(()->remove(id,e));e.onTimeout(()->remove(id,e));return e;}public void publish(Long id,String type,Object data){for(SseEmitter e:emitters.getOrDefault(id,List.of()))try{e.send(SseEmitter.event().name(type).data(data));}catch(IOException x){remove(id,e);}}private void remove(Long id,SseEmitter e){emitters.getOrDefault(id,List.of()).remove(e);}}
